	local last = 0
	playerlistloop = run.RenderStepped:Connect(function()
		local now = clock()
		if not playerlist.on then return end

		if not (overlaydrag and overlaydrag.panel == playerlist) and now - last >= 0.5 then
			last = now
			R.paintplayerlist()
		end
		R.tickplmarquee()
	end)
end

